import {processAutomationFollowup} from '@/lib/automation-followup-service';
import {ProspectingBudgetError} from '@/lib/voice-budget-failure';
import {OwnerPreviewRateLimitError,OwnerExportCapacityBusyError} from '@/lib/owner-enrichment-deferral';
import {OwnerExportPreflightPendingError,OwnerPreflightCleanupPendingError,OwnerCheckingCleanupPendingError} from '@/lib/owner-export-preflight';
import {dispatchCustomerUpdate} from '@/lib/customer-updates-service';
import {automationWorkReady,newLiveWorkKinds,deferUnstartedAutomation} from '@/lib/live-work-admission';
import {dispatchAttentionNotification} from '@/lib/attention-notifications-service';
import {dispatchTextMessage} from '@/lib/text-message-service';
import {expandMarket} from '@/lib/market-expansion-service';
import {processTextAi} from '@/lib/text-ai-service';
import {dispatchTitleFollowup} from '@/lib/title-followup-service';
import {prepareFulfillment} from '@/lib/fulfillment-service';
import {NextResponse} from 'next/server';
import {db} from '@/lib/stripe-test';
import {discoverForAccount} from '@/lib/discovery-service';
import {refreshSigning} from '@/lib/signing-service';
import {reconcileLiveConversation} from '@/lib/live-conversation-service';
import {dispatchLiveVoice} from '@/lib/live-dispatch-service';
import {enrichForAccount} from '@/lib/owner-enrichment-service';
export const dynamic='force-dynamic';
// DealMachine's synchronous export permits 120 seconds, plus bounded original
// receipt/download and independent persistence deadlines.
export const maxDuration=240;
/** Short-lived, one-use DB capabilities; no credentials or account IDs accepted from requests. */
export async function POST(request:Request){
 const billingDeadline=AbortSignal.timeout(45000);
 const headers={'Cache-Control':'private, no-store'};
 const token=request.headers.get('authorization')?.replace(/^Bearer /,'');
 if(!token||!/^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}){2}$/.test(token))return NextResponse.json({error:'Unauthorized'},{status:401,headers});
 let ticket:{id:string;accountId:string;kind:string;screeningId:string|null;liveCallId:string|null;signingId:string|null;voiceJobId:string|null;fulfillmentJobId:string|null;titleTaskId:string|null;textAiJobId:string|null;marketResearchJobId:string|null;openerMessageId:string|null}|null=null;
 const finishHeldAttempt=async(confirmForWorker:boolean)=>{
  if(!ticket)return false;
  try{
   if(ticket.kind==='contacts')return await db<boolean>('rpc/icash_finish_owner_enrichment','POST',{p_id:ticket.id,p_account:ticket.accountId,p_screening:ticket.screeningId,p_token:token,p_success:false,p_outcome:'held_for_reconciliation'})===true&&confirmForWorker;
   await db('rpc/icash_finish_automation','POST',{p_id:ticket.id,p_success:false,p_outcome:'held_for_reconciliation'});
   if(!confirmForWorker)return false;
   // The legacy finish RPC returns void even when its conditional update did
   // not match. Confirm this exact consumed capability reached its durable hold
   // before telling the worker it can continue with another independent job.
   const saved=await db<Array<{id:string;account_id:string;kind:string;token:string;state:string;outcome:string}>>(`icash_automation_tickets?id=eq.${encodeURIComponent(ticket.id)}&account_id=eq.${encodeURIComponent(ticket.accountId)}&token=eq.${encodeURIComponent(token)}&select=id,account_id,kind,token,state,outcome&limit=1`);
   return Array.isArray(saved)&&saved.length===1&&saved[0].id===ticket.id&&saved[0].account_id===ticket.accountId&&saved[0].kind===ticket.kind&&saved[0].token===token&&saved[0].state==='held'&&saved[0].outcome==='held_for_reconciliation';
  }catch{return false;}
 };
 const heldResponse=(acknowledged:boolean)=>NextResponse.json({status:'held_for_reconciliation'},{status:503,headers:{...headers,...(acknowledged?{'X-iCash-Automation-Outcome':'job-held'}:{})}});
 try{
  ticket=await db('rpc/icash_consume_automation','POST',{p_token:token});
  if(!ticket)return NextResponse.json({error:'Expired or consumed'},{status:401,headers});
  if(ticket.kind==='account_reconcile')return NextResponse.json(await processAutomationFollowup(db,ticket.accountId,ticket.id),{headers});
  const result=!automationWorkReady(ticket.kind)&&newLiveWorkKinds.has(ticket.kind)?await deferUnstartedAutomation(db,ticket,token):ticket.kind==='customer_updates'?await dispatchCustomerUpdate(ticket.accountId,{db,signal:billingDeadline}):ticket.kind==='customer_attention'?await dispatchAttentionNotification(ticket.accountId,{db,signal:billingDeadline}):['seller_opener','seller_recovery'].includes(ticket.kind)&&ticket.openerMessageId?await dispatchTextMessage(ticket.accountId,ticket.openerMessageId):ticket.kind==='market_research'&&ticket.marketResearchJobId?await expandMarket(ticket.accountId,ticket.marketResearchJobId):ticket.kind==='text_ai'&&ticket.textAiJobId?await processTextAi(ticket.accountId,ticket.textAiJobId):ticket.kind==='title_followup'&&ticket.titleTaskId?await dispatchTitleFollowup(ticket.accountId,ticket.titleTaskId):ticket.kind==='fulfillment'&&ticket.fulfillmentJobId?await prepareFulfillment(ticket.accountId,ticket.fulfillmentJobId):ticket.kind==='voice_dispatch'&&ticket.voiceJobId?await dispatchLiveVoice(ticket.accountId,ticket.voiceJobId,{ticketId:ticket.id,token}):ticket.kind==='signing_result'&&ticket.signingId?await refreshSigning(ticket.accountId,ticket.signingId):ticket.kind==='voice_result'&&ticket.liveCallId?await reconcileLiveConversation(ticket.accountId,ticket.liveCallId):ticket.kind==='discovery'?await discoverForAccount(ticket.accountId):ticket.kind==='contacts'&&ticket.screeningId?await enrichForAccount(ticket.accountId,ticket.screeningId):{status:'held'};
  const success=['no_new_properties','inventory_advancing','inventory_market_changed','inventory_waiting','seller_inventory_unavailable','seller_contact_spacing','supply_target_met','updates_disabled','updates_idle','updates_held','updates_accepted','attention_disabled','attention_idle','attention_held','attention_accepted','market_research_saved','waiting_for_daytime_budget','waiting_for_available_credits','waiting_for_active_call','text_ai_drafted','text_ai_handoff','message_accepted','title_followup_sent','fulfillment_prepared','call_started','outside_contact_hours','screening_queued','empty','contacts_saved','conversation_saved','awaiting_conversation','awaiting_counterparty','customer_signature_needed','completed','test_completed'].includes(result.status);
  if(ticket.kind==='contacts')await db('rpc/icash_finish_owner_enrichment','POST',{p_id:ticket.id,p_account:ticket.accountId,p_screening:ticket.screeningId,p_token:token,p_success:success,p_outcome:result.status});
  else await db('rpc/icash_finish_automation','POST',{p_id:ticket.id,p_success:success,p_outcome:result.status});
  // Finishing primary work atomically queues account reconciliation in SQL.
  // Return the worker slot immediately; original receipts and notifications
  // have independent durable claims and cannot replay this operation.
  return NextResponse.json({status:result.status,billing:{status:'queued'}},{headers});
 }catch(error){
  if(ticket?.kind==='contacts'&&ticket.screeningId&&error instanceof OwnerPreviewRateLimitError
   &&error.accountId===ticket.accountId&&error.screeningId===ticket.screeningId
   &&error.operationKey===`owners:${ticket.accountId}:${ticket.screeningId}`){
   if(error instanceof OwnerExportCapacityBusyError)console.info('automation_waiting',{kind:'contacts',reason:'OWNER_EXPORT_CAPACITY_BUSY'});
   // The RPC checks the exact consumed capability and absence of all paid-work
   // evidence under lock. It schedules a new capability, never reuses this token.
   const cleanup=error instanceof OwnerPreflightCleanupPendingError,checkingCleanup=error instanceof OwnerCheckingCleanupPendingError;
   if(checkingCleanup)console.info('automation_waiting',{kind:'contacts',reason:'OWNER_CHECKING_CLEANUP_PENDING'});
   const deferral=checkingCleanup?'rpc/icash_defer_expired_checking_cleanup':cleanup?'rpc/icash_defer_owner_preflight_cleanup':error instanceof OwnerExportPreflightPendingError?'rpc/icash_defer_owner_preflight':'rpc/icash_defer_owner_enrichment';
   try{if(await db<boolean>(deferral,'POST',{p_id:ticket.id,p_account:ticket.accountId,p_screening:ticket.screeningId,p_token:token,p_operation:error.operationKey,...(cleanup||checkingCleanup?{p_preflight:error.preflightId}:{})})===true)return NextResponse.json({status:checkingCleanup?'owner_checking_cleanup_pending':cleanup?'owner_preflight_cleanup_pending':error instanceof OwnerExportPreflightPendingError?'owner_export_preflight_pending':'owner_preview_rate_limited'},{headers});}catch{/* An uncertain database outcome is never treated as a retry grant. */}
   // A lost deferral response may already have led to a fresh issued/consumed
   // capability. Never let this stale worker finish that newer attempt by ID.
   console.error('automation_held',{kind:'contacts',reason:checkingCleanup?'OWNER_CHECKING_CLEANUP_DEFERRAL_HELD':error instanceof OwnerExportPreflightPendingError?'OWNER_PREFLIGHT_DEFERRAL_HELD':'OWNER_PREVIEW_DEFERRAL_HELD'});
   return heldResponse(await finishHeldAttempt(true));
  }
  if(ticket&&error instanceof ProspectingBudgetError){
   try{if(await db<boolean>('rpc/icash_hold_prospecting_ticket','POST',{p_id:ticket.id,p_account:ticket.accountId,p_quote:error.quoteCents}))return NextResponse.json({status:'prospecting_budget_held'},{headers});}catch{/* Unknown outcomes retain reconciliation. */}
  }
  // Fixed codes only: never log provider bodies, account details or capabilities.
  // Active owner exports bypass the legacy enrichment logger. Preserve their
  // exact fixed failure code for operators, without interpreting it as retry
  // permission or changing the durable reconciliation outcome below.
  const contactReasons=['OWNER_PREVIEW_FAILED_NO_RETRY','OWNER_PREVIEW_SAVE_UNCONFIRMED','OWNER_LOOKUP_FAILED_NO_RETRY','OWNER_EXPORT_RECONCILIATION_REQUIRED','OWNER_EXPORT_RECEIPT_SAVE_UNCONFIRMED','OWNER_EXPORT_RESPONSE_UNAVAILABLE','OWNER_EXPORT_RESPONSE_TOO_LARGE','OWNER_EXPORT_DOWNLOAD_UNAVAILABLE','OWNER_EXPORT_CAPACITY_BUSY','OWNER_CHECKING_CLEANUP_HELD','OWNER_CHECKING_CLEANUP_UNCONFIRMED','OWNER_CHECKING_CONTINUATION_HELD'];
  const checkingInfrastructureReasons=['OWNER_EXPORT_RECOVERY_UNAVAILABLE','OWNER_CONTINUATION_SOURCE_UNAVAILABLE','OWNER_CHECKING_CLEANUP_ADMISSION_UNAVAILABLE','OWNER_CHECKING_CLEANUP_ADMISSION_INVALID','OWNER_CHECKING_CLEANUP_CLAIM_UNAVAILABLE','OWNER_CHECKING_CLEANUP_RECEIPT_UNAVAILABLE','OWNER_CHECKING_CLEANUP_RECEIPT_UNCONFIRMED'];
  const reason=error instanceof Error&&(['Database request failed','DISCOVERY_RATE_LIMIT','DISCOVERY_CONFIGURATION_INVALID','DISCOVERY_FILTER_INVALID','DISCOVERY_ESTIMATE_INVALID','DISCOVERY_RATE_TOO_LOW','DISCOVERY_PROVIDER_REQUEST_FAILED_NO_RETRY','DISCOVERY_RESPONSE_REQUIRES_RECONCILIATION','DISCOVERY_DELIVERY_REQUIRES_RECONCILIATION'].includes(error.message)||ticket?.kind==='contacts'&&[...contactReasons,...checkingInfrastructureReasons].includes(error.message))?error.message:'unclassified';
  const provider=error as {stage?:unknown;httpStatus?:unknown}|null;
  console.error('automation_held',{kind:ticket?.kind??'unclaimed',reason,...(reason==='DISCOVERY_PROVIDER_REQUEST_FAILED_NO_RETRY'?{stage:provider?.stage==='estimate'?'estimate':provider?.stage==='paid'?'paid':'unknown',httpStatus:typeof provider?.httpStatus==='number'&&Number.isInteger(provider.httpStatus)&&provider.httpStatus>=100&&provider.httpStatus<=599?provider.httpStatus:null}:{})});
  // Only recognized request/receipt failures are scoped to this job. Unknown
  // exceptions, database failures and invalid shared configuration retain the
  // worker's infrastructure backoff even if the ticket hold was saved.
  const isolatedJobFailure=ticket?.kind==='contacts'&&contactReasons.includes(reason)
   ||ticket?.kind==='discovery'&&['DISCOVERY_RATE_LIMIT','DISCOVERY_PROVIDER_REQUEST_FAILED_NO_RETRY','DISCOVERY_RESPONSE_REQUIRES_RECONCILIATION','DISCOVERY_DELIVERY_REQUIRES_RECONCILIATION'].includes(reason);
  return heldResponse(await finishHeldAttempt(isolatedJobFailure));
 }
}
